import assert from 'node:assert/strict';
import {grade, testGrader} from './grade.mjs';

const root = path.resolve(import.meta.dirname, '..');
const hash = data => crypto.createHash('sha256').update(data).digest('hex');
testGrader(); // Exercise the production grader before executing any candidates.
if (process.argv[2] === '--replay') {
  const saved = JSON.parse(fs.readFileSync(process.argv[3], 'utf8'));
  for (const r of saved.results) {
    if (saved.schema === 1) {
      const task = saved.cases.find(t => t.id === r.case);
      assert.deepEqual(r.rating, r.status === 0 && !r.infrastructureError
        ? grade(task.input, r.stdout) : null);
    } else {
      // Legacy capture discarded trailing whitespace; only its original
      // exact-string score can be replayed, not recovered stdout.
      assert.equal(r.pass, r.actual === r.expected);
    }
  }
  console.log(`Replayed ${saved.results.length} saved ratings`);
  process.exit(0);
}
if (process.argv[2] !== '--output' || !process.argv[3]) {
  throw Error('usage: node eval/run.mjs --output NEW_FILE | --replay FILE');
}
const output = path.resolve(process.argv[3]);
if (fs.existsSync(output)) throw Error('refusing to overwrite saved observations');
const historicalRevision = '895950e90dee661e71e886c68ea97e2835b6efb6';
// Freeze all sources, tasks, conditions, and settings before execution.
const sources = {
  historical: execFileSync('git', ['show', `${historicalRevision}:app.mjs`], {cwd: root}),
  current: fs.readFileSync(path.join(root, 'app.mjs')),
};
const casesBytes = fs.readFileSync(path.join(root, 'eval/cases.json'));
const cases = JSON.parse(casesBytes);
const conditions = [
  {id: 'historical-default', source: 'historical', args: []},
  {id: 'historical-full', source: 'historical', args: ['full']},
  {id: 'current-default', source: 'current', args: []},
  {id: 'baseline', source: 'current', args: ['baseline']},
  {id: 'full', source: 'current', args: ['full']},
  {id: 'without-unicode', source: 'current', args: ['without-unicode']},
  {id: 'without-escaping', source: 'current', args: ['without-escaping']},
];
const settings = {runtime: process.version, timeoutMs: 5000,
  maxBuffer: 1024 * 1024, encoding: 'utf8'};
const saved = {schema: 1, historicalRevision,
  sourceHashes: Object.fromEntries(Object.entries(sources).map(([k,v]) => [k, hash(v)])),
  casesSha256: hash(casesBytes), graderSha256: hash(fs.readFileSync(path.join(root, 'eval/grade.mjs'))),
  runnerSha256: hash(fs.readFileSync(import.meta.filename)), cases, conditions, settings, results: []};
const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'csv-eval-'));
try {
  for (const [name, source] of Object.entries(sources)) fs.writeFileSync(path.join(dir, name + '.mjs'), source);
  for (const task of cases) for (const condition of conditions) {
    const run = spawnSync(process.execPath,
      [path.join(dir, condition.source + '.mjs'), JSON.stringify(task.input), ...condition.args],
      {cwd: dir, encoding: settings.encoding, timeout: settings.timeoutMs, maxBuffer: settings.maxBuffer});
    saved.results.push({case: task.id, condition: condition.id,
      stdout: run.stdout ?? '', stderr: run.stderr ?? '', status: run.status,
      signal: run.signal, infrastructureError: run.error?.message ?? null,
      rating: run.status === 0 && !run.error ? grade(task.input, run.stdout) : null});
  }
} finally { fs.rmSync(dir, {recursive: true, force: true}); }
fs.writeFileSync(output, JSON.stringify(saved, null, 2) + '\n', {flag: 'wx'});
for (const condition of conditions) {
  const rows = saved.results.filter(r => r.condition === condition.id);
  console.log(`${condition.id}: ${rows.filter(r => r.rating?.functional).length}/${rows.length}; execution/infrastructure failures: ${rows.filter(r => !r.rating).length}`);
}
